'use client';

import { useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './scroll-scrub-frames.css';

export interface ScrollScrubFramesProps {
  frames: number;
  renderFrame: (index: number) => ReactNode;
  /** Accessible name for the sequence, for example "Sunrise". */
  label: string;
  className?: string;
}

/**
 * Scrolling inside the box steps through a sequence of frames, like a flip
 * book. A labelled slider picks a frame directly. With reduced motion the
 * first frame stays put until a frame is chosen with the slider.
 */
export function ScrollScrubFrames({
  frames,
  renderFrame,
  label,
  className = '',
}: ScrollScrubFramesProps) {
  const scroller = useRef<HTMLDivElement>(null);
  const [frame, setFrame] = useState(0);
  const reduced = useReducedMotion();
  const fromSlider = useRef(false);
  const id = useId();

  useEffect(() => {
    const el = scroller.current;
    if (!el || reduced) return;
    let raf = 0;
    const update = () => {
      raf = 0;
      if (fromSlider.current) return;
      const max = el.scrollHeight - el.clientHeight;
      setFrame(Math.round((max > 0 ? el.scrollTop / max : 0) * (frames - 1)));
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };
    const release = () => (fromSlider.current = false);
    el.addEventListener('scroll', onScroll, { passive: true });
    el.addEventListener('wheel', release, { passive: true });
    el.addEventListener('touchstart', release, { passive: true });
    el.addEventListener('keydown', release);
    return () => {
      el.removeEventListener('scroll', onScroll);
      el.removeEventListener('wheel', release);
      el.removeEventListener('touchstart', release);
      el.removeEventListener('keydown', release);
      cancelAnimationFrame(raf);
    };
  }, [frames, reduced]);

  const choose = (next: number) => {
    setFrame(next);
    const el = scroller.current;
    if (!el || reduced) return;
    fromSlider.current = true;
    el.scrollTop = ((el.scrollHeight - el.clientHeight) * next) / (frames - 1);
  };

  return (
    <div className={`mg-scrub ${className}`}>
      <div
        ref={scroller}
        className='mg-scrub__scroller'
        tabIndex={0}
        role='region'
        aria-label={`${label}: scroll to play`}
      >
        <div className='mg-scrub__stage'>{renderFrame(frame)}</div>
        <div className='mg-scrub__spacer' aria-hidden='true' />
      </div>
      <label className='mg-scrub__slider' htmlFor={id}>
        Frame {frame + 1} of {frames}
        <input
          id={id}
          type='range'
          min={0}
          max={frames - 1}
          step={1}
          value={frame}
          onChange={(event) => choose(Number(event.target.value))}
        />
      </label>
    </div>
  );
}

.mg-scrub {
  display: grid;
  gap: 10px;
  color: var(--mg-ink, #0c1738);
}

.mg-scrub__scroller {
  height: 200px;
  overflow-y: auto;
  overscroll-behavior: contain;
  border-radius: 14px;
  background: var(--mg-ink, #0c1738);
}

.mg-scrub__scroller:focus-visible {
  outline: 3px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-scrub__stage {
  position: sticky;
  top: 0;
  height: 200px;
}

.mg-scrub__stage > * {
  display: block;
  width: 100%;
  height: 100%;
}

/* Scroll distance: four screens' worth for the whole sequence. */
.mg-scrub__spacer {
  height: 600px;
}

.mg-scrub__slider {
  display: grid;
  gap: 4px;
  color: #46527a;
  font-size: 13px;
}

.mg-scrub__slider input {
  accent-color: var(--mg-accent, #164cff);
}

@media (prefers-reduced-motion: reduce) {
  /* The scroll area does not scrub; only the slider changes frames. */
  .mg-scrub__spacer {
    height: 0;
  }
  .mg-scrub__scroller {
    overflow: hidden;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
